import{g as a,ae as e,r as n,B as t}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"Document Resource","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data-fetching/document-resource.md","filePath":"docs/data-fetching/document-resource.md","lastUpdated":1790261415000}'),p={name:"docs/data-fetching/document-resource.md"};function c(o,s,d,l,r,i){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="document-resource" tabindex="-1">Document Resource <a class="header-anchor" href="#document-resource" aria-label="Permalink to “Document Resource”">​</a></h1><p><code>createDocumentResource</code> fetches one document from a Frappe backend and gives you methods to update, save and delete it, and to run its controller methods. It is the older data-fetching API and stays supported through <code>1.x</code>.</p><p>For new code, use <a href="./use-doc"><code>useDoc</code></a>.</p><h2 id="composition-api" tabindex="-1">Composition API <a class="header-anchor" href="#composition-api" aria-label="Permalink to “Composition API”">​</a></h2><p>Set <code>doctype</code> and <code>name</code>. The document is fetched when the resource is created and is available on <code>todo.doc</code>.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> v-if</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.doc</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">    {{ todo.doc.description }}</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">Badge</span><span class="s_1i4ay4"> :label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.doc.status</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.setValue.submit({ status: &#39;Closed&#39; })</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">      Mark as closed</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.sendEmail.submit({ email: todo.doc.owner })</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">      Send email</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">createDocumentResource</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createDocumentResource</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  whitelistedMethods</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">    sendEmail</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">send_email</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The resource sends dotted method names like <code>frappe.client.get</code>, so the app must use <a href="./resource#frappe-backend"><code>frappeRequest</code></a> as its fetcher.</p><p>There is one resource for each <code>doctype</code> and <code>name</code>. A second <code>createDocumentResource</code> call for the same document returns the same object.</p><h2 id="options-api" tabindex="-1">Options API <a class="header-anchor" href="#options-api" aria-label="Permalink to “Options API”">​</a></h2><p>With <code>app.use(FrappeUI, { resources: true })</code> in <code>main.js</code> (see <a href="./resource#options-api">Resource</a>), declare the resource with <code>type: &#39;document&#39;</code>. It is available on <code>this.$resources.todo</code>.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  resources</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">    todo</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">      return</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">        type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">document</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">        doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">        name</span><span class="s_1jjt6x">:</span><span class="s_118ozv"> this</span><span class="s_1jjt6x">.</span><span class="s_11933w">todoName</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">      }</span></span>
<span class="line"><span class="s_13ahmt">    }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API Reference”">​</a></h2><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>doctype</code></td><td></td><td>The DocType of the document. Required.</td></tr><tr><td><code>name</code></td><td></td><td>The name of the document. Required.</td></tr><tr><td><code>auto</code></td><td><code>true</code></td><td>Fetch the document when the resource is created.</td></tr><tr><td><code>whitelistedMethods</code></td><td></td><td>Controller methods to expose as resources, like <code>{ sendEmail: &#39;send_email&#39; }</code>. See <a href="#whitelisted-methods">Whitelisted methods</a>.</td></tr><tr><td><code>debounce</code></td><td><code>500</code></td><td>Wait time in milliseconds for <code>setValueDebounced</code>.</td></tr><tr><td><code>realtime</code></td><td><code>false</code></td><td>Fetch the document again when the server reports that it changed. Needs a socket on <code>this.$socket</code>, so it works only in the Options API.</td></tr><tr><td><code>onSuccess(doc)</code></td><td></td><td>Runs after the document loads.</td></tr><tr><td><code>onError(error)</code></td><td></td><td>Runs when loading the document fails.</td></tr><tr><td><code>transform(doc)</code></td><td></td><td>Changes the document before it is set on <code>doc</code>.</td></tr><tr><td><code>setValue</code></td><td></td><td>Object with <code>onSuccess</code>, <code>onError</code> and <code>validate</code> for <code>setValue</code>, <code>setValueDebounced</code> and <code>save</code>. Throw in <code>validate</code> to stop the request.</td></tr><tr><td><code>delete</code></td><td></td><td>Object with <code>onSuccess</code> and <code>onError</code> for <code>delete</code>.</td></tr></tbody></table><h3 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>doc</code></td><td>The document, after <code>transform</code>. <code>null</code> until it loads.</td></tr><tr><td><code>originalDoc</code></td><td>A copy of the document as last loaded or saved.</td></tr><tr><td><code>isDirty</code></td><td><code>true</code> when <code>doc</code> differs from <code>originalDoc</code>.</td></tr><tr><td><code>get</code></td><td>The <a href="./resource#properties">resource</a> that fetches the document. Read <code>get.loading</code>, <code>get.error</code> and <code>get.promise</code> here.</td></tr></tbody></table><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>reload()</code></td><td>Fetch the document again. Returns a promise.</td></tr><tr><td><code>setDoc(doc)</code></td><td>Replace <code>doc</code>. Pass a function to compute it from the current document.</td></tr></tbody></table><h3 id="write-resources" tabindex="-1">Write resources <a class="header-anchor" href="#write-resources" aria-label="Permalink to “Write resources”">​</a></h3><p>Each of these is a <a href="./resource#methods">resource</a> with its own <code>loading</code> and <code>error</code>. Call <code>submit()</code> to run it.</p><table tabindex="0"><thead><tr><th>Resource</th><th><code>submit()</code> argument</th><th>Description</th></tr></thead><tbody><tr><td><code>setValue</code></td><td><code>{ status: &#39;Closed&#39; }</code></td><td>Set field values. <code>doc</code> changes at once and goes back if the request fails.</td></tr><tr><td><code>setValueDebounced</code></td><td><code>{ description: &#39;…&#39; }</code></td><td>Same as <code>setValue</code>, sent once after <code>debounce</code> milliseconds without a new call.</td></tr><tr><td><code>save</code></td><td>none</td><td>Send the fields of <code>doc</code> that changed since it loaded. Sends no request when nothing changed.</td></tr><tr><td><code>delete</code></td><td>none</td><td>Delete the document and set <code>doc</code> to <code>null</code>.</td></tr></tbody></table><p>Rows of the same document in a <a href="./list-resource">list resource</a> update with <code>setValue</code>, <code>save</code> and <code>delete</code>.</p><h3 id="whitelisted-methods" tabindex="-1">Whitelisted methods <a class="header-anchor" href="#whitelisted-methods" aria-label="Permalink to “Whitelisted methods”">​</a></h3><p>Each key in <code>whitelistedMethods</code> becomes a resource on the document resource. <code>submit(args)</code> runs the controller method with <code>args</code>, and <code>data</code> is the method&#39;s return value.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createDocumentResource</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  whitelistedMethods</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">    sendEmail</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">send_email</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    close</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_12xt1b">      method</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">close</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">      onSuccess</span><span class="s_13ahmt">(</span><span class="s_fsg3al">result</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {}</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">    }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">todo</span><span class="s_1jjt6x">.</span><span class="s_11933w">sendEmail</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> email</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">jane@example.com</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_22m8k2">todo</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">close</span><span class="s_1jjt6x">.</span><span class="s_11933w">loading</span></span></code></pre></div><p>The value is the method name, or an object with <code>method</code> and any <a href="./resource#options">resource options</a>. If the response includes this document after the method ran, <code>doc</code> updates with it.</p>`,26)])])}const u=a(p,[["render",c]]);export{_ as __pageData,u as default};
